  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: radial-gradient(1200px 600px at 20% -10%, #eef0ff 0%, var(--bg) 60%);
}
.auth-card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border-radius: 20px;
  box-shadow: var(--shadow);
  padding: 34px 30px;
  text-align: center;
}
.auth-logo { font-size: 44px; }
.auth-card h1 { margin: 10px 0 4px; font-size: 24px; }
.auth-sub { color: var(--ink-soft); margin: 0 0 22px; font-size: 14px; }

.tabs {
  display: flex;
  background: #f0f2f8;
  border-radius: 12px;
  padding: 4px;
  margin-bottom: 20px;
}
.tab {
  flex: 1;
  border: 0;
  background: transparent;
  padding: 9px;
  border-radius: 9px;
  font-size: 14px;
  cursor: pointer;
  color: var(--ink-soft);
  font-weight: 600;
}
.tab.active { background: #fff; color: var(--primary); box-shadow: 0 2px 6px rgba(0,0,0,0.06); }

.auth-form { text-align: left; display: block; }
.auth-form label, .task-form label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
  margin: 12px 0 5px;
